    difficulty: 3,
    prompt: "Frosted glass Logos using GPT 1.5\nJSON prompt 👇🏻\nRestyle this image into\n{\n  \"target_style\": {\n    \"style_name\": \"WWDC25-inspired frosted glass aesthetic\",\n    \"visual_language\": [\n      \"sleek minimal design\",\n      \"modern UI aesthetic\",\n      \"volumetric lighting\",\n      \"subtle 3D emboss\",\n      \"glowing edges\"\n    ],\n    \"material_appearance\": {\n      \"base_material\": \"frosted glass\",\n      \"texture_quality\": \"smooth with subtle grain\",\n      \"finish\": \"semi-gloss with iridescent refraction\"\n    },\n    \"lighting_style\": {\n      \"source_type\": \"studio lightbox with volumetric lighting\",\n      \"intensity\": \"medium\",\n      \"shadows\": \"elegant soft shadows\",\n      \"highlight_behavior\": \"visible soft rainbow gradient highlights\"\n    },\n    \"color_palette\": {\n      \"dominant_colors\": [\n        \"#ffffff\",\n        \"#cccccc\"\n      ],\n      \"accent_colors\": [\n        \"#ff00ff\",\n        \"#00ffff\",\n        \"#ffff00\",\n        \"#ff9900\"\n      ],\n      \"contrast_level\": \"medium\",\n      \"overall_tone\": \"cool with iridescent accents.\"\n    },\n    \"rendering_style\": {\n      \"dimensionality\": \"2.5D\",\n      \"resolution_quality\": \"high fidelity\",\n      \"depth_effects\": \"subtle embossing and glowing edge lighting\"\n    }\n  },\n  \"output_settings\": {\n    \"aspect_ratio\": \"1:1\",\n    \"background_handling\": \"white background\",\n    \"object_focus\": \"preserve geometry, retexture with full material and lighting transformation.\"\n  }\n}",
    rawBlock: "Frosted glass Logos using GPT 1.5\nJSON prompt 👇🏻\nRestyle this image into\n{\n  \"target_style\": {\n    \"style_name\": \"WWDC25-inspired frosted glass aesthetic\",\n    \"visual_language\": [\n      \"sleek minimal design\",\n      \"modern UI aesthetic\",\n      \"volumetric lighting\",\n      \"subtle 3D emboss\",\n      \"glowing edges\"\n    ],\n    \"material_appearance\": {\n      \"base_material\": \"frosted glass\",\n      \"texture_quality\": \"smooth with subtle grain\",\n      \"finish\": \"semi-gloss with iridescent refraction\"\n    },\n    \"lighting_style\": {\n      \"source_type\": \"studio lightbox with volumetric lighting\",\n      \"intensity\": \"medium\",\n      \"shadows\": \"elegant soft shadows\",\n      \"highlight_behavior\": \"visible soft rainbow gradient highlights\"\n    },\n    \"color_palette\": {\n      \"dominant_colors\": [\n        \"#ffffff\",\n        \"#cccccc\"\n      ],\n      \"accent_colors\": [\n        \"#ff00ff\",\n        \"#00ffff\",\n        \"#ffff00\",\n        \"#ff9900\"\n      ],\n      \"contrast_level\": \"medium\",\n      \"overall_tone\": \"cool with iridescent accents.\"\n    },\n    \"rendering_style\": {\n      \"dimensionality\": \"2.5D\",\n      \"resolution_quality\": \"high fidelity\",\n      \"depth_effects\": \"subtle embossing and glowing edge lighting\"\n    }\n  },\n  \"output_settings\": {\n    \"aspect_ratio\": \"1:1\",\n    \"background_handling\": \"white background\",\n    \"object_focus\": \"preserve geometry, retexture with full material and lighting transformation.\"\n  }\n}",
