    images: [{"src":"https://media.aiartspell.art/images/prompts/20251201/nintendo-style-3d-cartoon-illustration.png","alt":"任天堂风格的3D卡通插画","width":500,"isThumb":false},{"src":"https://img1.aiart.pics/images/prompts/20251201/116-2.jpeg","alt":"任天堂风格的3D卡通插画","width":500,"isThumb":false}],
